  // ---------- technique cards (shown before a drill the first time, and on demand) ----------
  const TECHNIQUES = {
    glance: { title: 'Glance (Kim\'s Game)', what: 'A grid of objects flashes for a few seconds. Then pick out the ones you saw from a mix that includes decoys.',
      how: ['Name every item silently as you see it ("key, frog, kite"). Naming is faster to remember than a picture alone.',
        'Chunk: group items by category or link them into a silly mini-story (the frog flew the kite with a key).',
        'Sweep in a fixed order (rows, left to right). Don\'t get stuck on one item.',
        'Selecting a decoy costs you a point, so leave items you\'re unsure about.'],
      why: 'This is the scout and sniper "Kim\'s Game" warm-up. Treat it as practice at quick encoding, not a general memory boost: brain-training gains mostly stay with the trained task.' },
    change: { title: 'Spot the Change', what: 'You see a grid, it blinks, and one thing is different: swapped, moved, added or removed. Click where it changed.',
      how: ['You only see what you attend to (change blindness). Memorize position plus identity, not a vague impression.',
        'Scan in the same order every time, and verbally anchor the corners and edges.',
        'In the second view, compare region by region against your mental list rather than waiting for something to "pop".',
        'If something disappeared, click the now-empty cell.'],
      why: 'In change-blindness studies people miss large changes they aren\'t attending to (Simons & Levin 1998). Expertise helps mainly with meaningful changes in a familiar domain, so practice the systematic scan, not hope.' },
    scene: { title: 'Room Recall', what: 'Walk into a room: study it for a few seconds, optionally narrate what you see, then answer questions about it.',
      how: ['Use a fixed scan path: left wall, back wall, right wall, then the people, then the table from left to right.',
        'Narrate in words: "Rain outside, clock 3:25, blue star in frame, door open". Describing is the evidence-backed core of observation training.',
        'Grab the "boring" facts people skip: times, dates, numbers, open or closed, on or off, counts.',
        'Last pass: ask "what doesn\'t belong here?"'],
      why: 'Medical students who practiced detailed description of artwork reported more details in patient photos afterward (Dolev et al. 2001; Naghshineh et al. 2008). Describe first, interpret second.' },
    faces: { title: 'Faces & Names', what: 'Meet a few people (face, name, job, one detail), then get quizzed. People you meet come back days later for spaced review.',
      how: ['Look for one distinctive feature: ears, a mark, glasses, hair, beard.',
        'Say the name back. In the drill you type it, in real life you say "Nice to meet you, Maya".',
        'Link the name to one meaningful fact (Maya, the nurse who grew up in Duluth).',
        'Recall it again a minute later, then the next day. Retrieval at growing intervals beats elaborate imagery for real-world names (Morris et al. 2005).'],
      why: 'Names are hard because they\'re arbitrary labels: "Baker" the surname is harder to remember than "baker" the job. Spaced retrieval of names, and real people in the People Log, is where the real gain comes from.' },
    palace: { title: 'Memory Palace', what: 'Store a list of words along a route you know well, then recall them in order.',
      how: ['Use a real route you know cold (your apartment, your walk to class). Set up your stops once in the drill.',
        'At each stop, picture the item interacting with the place, exaggerated and odd: a giant anvil crushing the shoe rack.',
        'Add motion, sound or smell, and make it absurd. Boring images fade.',
        'To recall, walk the route in your head and look at each stop.'],
      why: 'People with no memory training who practiced this for about 6 weeks (30 min a day) went from about 26 to about 62 of 72 words, and kept much of the gain 4 months later (Dresler et al. 2017). It\'s for lists and ordered material: agendas, steps, talking points.' },
    reason: { title: 'Read the Room', what: 'Practice the reasoning half: separate what you saw from what you concluded, weigh explanations, ask the question that would tell them apart, and say how sure you are.',
      how: ['Observation is what your senses directly register (what a camera or thermometer would record). Inference is everything else. Keep them in separate columns.',
        'Generate at least three explanations before choosing one, and argue the opposite of your first guess.',
        'Check base rates: how common is each explanation to begin with?',
        'Ask what question or check would tell the explanations apart. Questions beat staring at body language.',
        'Put a number on it. Your calibration chart in Stats shows whether your 80% really means 80%.'],
      why: 'People average about 54% at telling lies from truths (Bond & DePaulo 2006), and single "tells" like gaze aversion are myths. Interview strategies and probabilistic thinking hold up much better (Vrij et al. 2017; Hartwig et al. 2006; Mellers et al. 2014).' },
    convo: { title: 'Conversation Recall', what: 'Someone introduces themselves out loud, the way people do at a club meeting or a first day. Then you\'re asked what they told you.',
      how: ['Listen for the hooks people always give: where they\'re from, what they study or do, someone they mention, what\'s coming up for them.',
        'Repeat the name back silently in the first second ("Maya. Maya Okafor."). The name is the first thing to go.',
        'Attach each fact to a picture of them: Maya holding shawarma in Buffalo, playing piano.',
        'Notice numbers and names of third parties (a cousin, a roommate). People notice when you remember them.'],
      why: 'Recalling what someone told you, instead of just hearing it again, is what makes it last: practicing recall beat rereading on tests days later (Roediger & Karpicke 2006).' },
    witness: { title: 'Witness', what: 'Watch a short scene: people come in, pick things up, hand them over and leave. Then answer questions like an eyewitness.',
      how: ['Give each person a label the moment they appear ("green shirt, hat") and keep using it.',
        'Narrate the action in short sentences as it happens: "Red takes the umbrella. Blue leaves."',
        'Track who is holding what, and who leaves with something.',
        'Keep count of who is in the room, and the order things happened in (first, last, right after).'],
      why: 'Eyewitness memory is reconstructive: later information, including leading questions, can change what people remember (Loftus 2005). Labeling and narrating while you watch gives you a record to recall from.' },
    describe: { title: 'Describe It', what: 'A room stays on screen while you write down everything you see. Then you check your description against the full list of what was there.',
      how: ['Describe before you interpret: "red mug, clock 3:25", not "someone was having coffee".',
        'Use a fixed path: left wall, back wall, right wall, people, table from left to right.',
        'Write down the boring facts: counts, times, numbers, on or off, open or closed.',
        'Finish with a last pass for anything that doesn\'t belong.'],
      why: 'This mirrors the core exercise in the art-observation studies: medical students who practiced describing artwork in detail reported more details in patient photos afterward (Dolev et al. 2001; Naghshineh et al. 2008).' },
    numbers: { title: 'Numbers', what: 'A number flashes (a phone number, a part number, a date). Type it back from memory.',
      how: ['Chunk it: 6175550193 is 617 · 555 · 0193, not ten separate digits.',
        'Learn the major system: each digit is a consonant sound, and you add vowels to make words. 0 s/z, 1 t/d, 2 n, 3 m, 4 r, 5 l, 6 j/sh/ch, 7 k/hard g, 8 f/v, 9 p/b.',
        'So 14 is t-r: "tire". 92 is p-n: "pan". Picture a tire rolling into a frying pan for 1492.',
        'Put long numbers on your memory palace route, one picture per stop.'],
      why: 'Plain digit span is about 7 for most people (Miller 1956). With practice and meaningful chunking, one student pushed his span to about 80 digits (Ericsson, Chase & Faloon 1980). Memory athletes turn digits into images with codes like the major system and place them on a memory-palace route.' },
    estimate: { title: 'Estimation', what: 'Answer quantity questions with a range you\'re 90% sure contains the true value. Your goal is to be right about 9 times in 10, with ranges as tight as that allows.',
      how: ['Start from something you know (a reference point), then adjust: "A floor is about 3 m, the building has about 100 floors…".',
        'Set the low end so you\'d be surprised if the truth were lower, then do the same for the high end.',
        'Most people\'s "90%" ranges catch the truth far less often. If you\'re missing, widen your ranges.',
        'Ranges get capped at higher levels (high ÷ low), so huge "safe" ranges stop counting.'],
      why: 'When people give ranges they say they\'re 90% or even 98% sure of, the truth falls outside far more often than it should (Alpert & Raiffa 1982; Moore & Healy 2008). Feedback on your own hit rate helps, though in Alpert & Raiffa\'s study it reduced overconfidence without removing it.' },
  };

